import{_ as s,o as a,c as t,a4 as l}from"./chunks/framework.vNSRaLQv.js";const c=JSON.parse('{"title":"Office 分页错位问题排查与解决记录","description":"","frontmatter":{"title":"Office 分页错位问题排查与解决记录","date":"2026-08-09T00:00:00.000Z"},"headers":[],"relativePath":"posts/Office分页错位排查记录.md","filePath":"posts/Office分页错位排查记录.md"}'),e={name:"posts/Office分页错位排查记录.md"};function h(n,i,k,p,r,o){return a(),t("div",null,[...i[0]||(i[0]=[l(`<h1 id="office-分页错位问题排查与解决记录" tabindex="-1">Office 分页错位问题排查与解决记录 <a class="header-anchor" href="#office-分页错位问题排查与解决记录" aria-label="Permalink to &quot;Office 分页错位问题排查与解决记录&quot;">​</a></h1><p>日期：2026-08-09 环境：Debian GNU/Linux 13 (trixie)，OnlyOffice 9.4.0 问题文件：<code>2026届工作证明（模板）.doc</code>（WPS Office 12.1 生成）</p><h2 id="一、问题现象" tabindex="-1">一、问题现象 <a class="header-anchor" href="#一、问题现象" aria-label="Permalink to &quot;一、问题现象&quot;">​</a></h2><p>标准 MS Office / WPS 中该文档为 <strong>2 页</strong>：</p><ul><li>第 1 页：标题&quot;工作证明&quot;到&quot;学校毕业生就业中心审定签名、公章：&quot;</li><li>第 2 页：&quot;注意：此材料不需等到答辩当天...&quot;等注意事项</li></ul><p>但在 OnlyOffice 中打开，<strong>&quot;注意&quot;内容跑到了第 1 页底部</strong>，分页错位。</p><h2 id="二、排查过程" tabindex="-1">二、排查过程 <a class="header-anchor" href="#二、排查过程" aria-label="Permalink to &quot;二、排查过程&quot;">​</a></h2><h3 id="_1-排除字体缺失因素" tabindex="-1">1. 排除字体缺失因素 <a class="header-anchor" href="#_1-排除字体缺失因素" aria-label="Permalink to &quot;1. 排除字体缺失因素&quot;">​</a></h3><p>先用 catdoc / antiword 提取文档内容，再用 Python 解析 .doc 的 OLE 结构、字体表（STTBF）和文本流，确认文档使用的字体：</p><ul><li>Times New Roman（英文）</li><li>宋体（正文）</li><li>华文行楷（标题）</li><li>仿宋</li><li>微软雅黑</li></ul><p>补齐缺失字体后，文字显示正常，但<strong>分页依旧错位</strong>——证明问题不在字体，而在分页机制。</p><h3 id="_2-分析文档分页结构" tabindex="-1">2. 分析文档分页结构 <a class="header-anchor" href="#_2-分析文档分页结构" aria-label="Permalink to &quot;2. 分析文档分页结构&quot;">​</a></h3><p>用 Python 解析 piece table 提取完整文本流，确认：</p><ul><li>文档文本中<strong>没有显式分页符（0x0C）</strong></li><li>&quot;注意&quot;段前只有若干空行（<code>\\r</code>），无任何分页标记</li><li>全文档 30 段，第 23 段是&quot;注意&quot;开头</li></ul><p>即：<strong>原文档靠&quot;第一页恰好排满 → 自然溢出分页&quot;</strong>，没有强制分页指令。</p><h3 id="_3-定位根因" tabindex="-1">3. 定位根因 <a class="header-anchor" href="#_3-定位根因" aria-label="Permalink to &quot;3. 定位根因&quot;">​</a></h3><p>分页位置 = 内容总行高 ÷ 每页可容纳高度。不同渲染器对字体行高、行距的浮点计算存在微小差异，累积后导致分页点偏移：</p><ul><li>WPS/MS Office：第一页恰好排到&quot;学校毕业生就业中心审定签名、公章&quot;</li><li>OnlyOffice：行高计算略有差异，第一页多容纳了几行，&quot;注意&quot;被挤进第一页</li></ul><h2 id="三、解决方案" tabindex="-1">三、解决方案 <a class="header-anchor" href="#三、解决方案" aria-label="Permalink to &quot;三、解决方案&quot;">​</a></h2><p>给&quot;注意&quot;段添加<strong>强制分页属性</strong>（<code>pageBreakBefore</code>），让分页不依赖自然排版，任何软件打开都稳定两页。</p><h3 id="具体操作" tabindex="-1">具体操作 <a class="header-anchor" href="#具体操作" aria-label="Permalink to &quot;具体操作&quot;">​</a></h3><p>用 OnlyOffice 自带的转换器 <code>x2t</code> 把 .doc 转成 .docx：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">/opt/onlyoffice/desktopeditors/converter/x2t</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /tmp/workcert.doc</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /tmp/workcert.docx</span></span></code></pre></div><p>然后解压 docx，在 <code>word/document.xml</code> 中定位&quot;注意&quot;所在段落的 <code>&lt;w:pPr&gt;</code>，在开头插入：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">&lt;</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">w</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">pageBreakBefore</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">/&gt;</span></span></code></pre></div><p>效果：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">&lt;</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">w</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">p</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">  &lt;</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">w</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">pPr</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">    &lt;</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">w</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">pageBreakBefore</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">/&gt;</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">          &lt;!-- 强制此段从新页开始 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">    &lt;</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">w</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">pStyle</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;"> w</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;">val</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">=</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">Normal</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    ...</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">  &lt;/</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">w</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">pPr</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">  &lt;</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">w</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">r</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">&gt;</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">...注意：此材料不需等到答辩当天...</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">&lt;/</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">w</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">r</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">&lt;/</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">w</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">p</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">&gt;</span></span></code></pre></div><p>重新打包为 docx 即可。</p><h2 id="四、经验总结" tabindex="-1">四、经验总结 <a class="header-anchor" href="#四、经验总结" aria-label="Permalink to &quot;四、经验总结&quot;">​</a></h2><ol><li><strong>&quot;自然分页&quot;在不同渲染器间不可靠</strong>。同一文档在 WPS 排满一页，在 OnlyOffice 可能少几行或多几行，导致分页点偏移。</li><li>若文档需要稳定的分页位置，应使用<strong>显式分页符</strong>（Word 里 Ctrl+Enter / 段落属性&quot;段前分页&quot;），而不是依赖内容排满。</li><li>排查思路：先排除字体因素（<code>fc-match</code> 验证匹配、清除 OnlyOffice 缓存），再检查分页结构（有无显式分页符）。</li><li>.doc 二进制格式可通过 Python + <code>olefile</code> 解析 piece table 提取文本流，定位分页符（0x0C）位置；或直接用 x2t 转成 docx 后按 XML 处理。</li></ol>`,30)])])}const g=s(e,[["render",h]]);export{c as __pageData,g as default};
